let settingsTab='audio';
const settingsPanelWords={ko:['사운드','조작','화면','데이터','BGM 음량','효과음 음량','BGM 듣기','효과음 듣기','조작 시험 · 실제 주행에는 영향을 주지 않습니다.','절전: 효과를 줄여 배터리 사용을 낮춥니다.\n균형: 선명도와 성능의 균형을 맞춥니다.\n고품질: 높은 해상도와 시각 효과를 사용합니다.','소리를 켜야 미리 들을 수 있습니다.','BGM을 켜야 미리 들을 수 있습니다.','현재 음량으로 재생합니다.'],en:['Sound','Controls','Display','Data','Music volume','Effects volume','Play music','Test effects','Control test · Does not affect your run.','Power saving: fewer effects.\nBalanced: clarity and performance.\nHigh: higher resolution and visual effects.','Enable sound to preview.','Enable music to preview.','Playing at the current volume.'],ja:['サウンド','操作','画面','データ','BGM音量','効果音音量','BGM試聴','効果音試聴','操作テスト · プレイに影響しません。','省電力：効果を削減\nバランス：画質と動作を両立\n高画質：高解像度と視覚効果','サウンドをオンにしてください。','BGMをオンにしてください。','現在の音量で再生します。'],zh:['声音','操控','画面','数据','音乐音量','音效音量','试听音乐','试听音效','操控测试 · 不影响实际游戏。','省电：减少特效\n均衡：平衡画质与性能\n高画质：更高分辨率和视觉效果','请先开启声音。','请先开启音乐。','按当前音量播放。']};
const sensitivityWords={ko:['조작 감도','낮추면 정밀하게, 높이면 빠르게 좌우 이동합니다. 버튼·조이스틱·키보드에 적용됩니다.','기본 감도 100%'],en:['Steering sensitivity','Lower for finer movement; higher for faster steering. Applies to buttons, joystick and keyboard.','Reset to 100%'],ja:['操作感度','低くすると細かく、高くすると素早く左右移動。ボタン・ジョイスティック・キーボードに適用。','標準の100%に戻す'],zh:['操控灵敏度','调低可精细移动，调高可快速转向。适用于按钮、摇杆和键盘。','恢复默认100%']};
function syncSteeringSensitivity(){const w=sensitivityWords[settings.language]||sensitivityWords.ko,percent=Math.round(settings.steeringSensitivity*100);$('steeringSensitivity').value=percent;$('steeringSensitivityValue').textContent=percent+'%';$('steeringSensitivityLabel').textContent=w[0];$('steeringSensitivityHint').textContent=w[1];$('steeringSensitivityReset').textContent=w[2];}
function setSteeringSensitivity(percent){const value=Number(percent);settings.steeringSensitivity=Number.isFinite(value)?Math.max(.5,Math.min(1.5,value/100)):1;syncSteeringSensitivity();moveSettingsTest(Number($('testSteerAxis').value)||0);persistSettings();}
$('steeringSensitivity').oninput=()=>setSteeringSensitivity($('steeringSensitivity').value);$('steeringSensitivityReset').onclick=()=>setSteeringSensitivity(100);
function syncSettingsPanel(){syncSteeringSensitivity();const w=settingsPanelWords[settings.language]||settingsPanelWords.ko;$('optionsPanel').setAttribute('data-tab',settingsTab);['Audio','Controls','Display','Data'].forEach((key,i)=>{const button=$('settingsTab'+key);button.textContent=w[i];button.setAttribute('aria-pressed',String(settingsTab===key.toLowerCase()))});for(const [key,index]of [['bgmVolume',4],['sfxVolume',5]]){$(key).value=Math.round(settings[key]*100);$(key+'Value').textContent=Math.round(settings[key]*100)+'%';$(key+'Label').textContent=w[index]}$('testBGM').textContent=w[6];$('testSFX').textContent=w[7];$('controlTestLabel').textContent=w[8];$('graphicsGuide').textContent=w[9];$('testSteerShip').style.transform='translateX(0)';$('testSteerAxis').value=0;}
for(const key of ['Audio','Controls','Display','Data'])$('settingsTab'+key).onclick=()=>{settingsTab=key.toLowerCase();syncSettingsPanel()};
for(const key of ['bgmVolume','sfxVolume'])$(key).oninput=()=>{settings[key]=Math.max(0,Math.min(100,Number($(key).value)||0))/100;$(key+'Value').textContent=Math.round(settings[key]*100)+'%';updateFlightAudio();updateMusic();persistSettings()};
function testSettingsAudio(kind){const w=settingsPanelWords[settings.language]||settingsPanelWords.ko;if(!settings.sound){$('audioTestStatus').textContent=w[10];return}if(kind==='bgm'&&!settings.bgm){$('audioTestStatus').textContent=w[11];return}flightAudioUnlock();updateFlightAudio();if(kind==='bgm')unlockMusic();else flightSfx('coin');$('audioTestStatus').textContent=w[12]}
$('testBGM').onclick=()=>testSettingsAudio('bgm');$('testSFX').onclick=()=>testSettingsAudio('sfx');
function moveSettingsTest(value){$('testSteerShip').style.transform='translateX('+(value*.45*settings.steeringSensitivity)+'px)'}
$('testSteerLeft').onclick=()=>moveSettingsTest(-100);$('testSteerRight').onclick=()=>moveSettingsTest(100);$('testSteerAxis').oninput=()=>moveSettingsTest(Number($('testSteerAxis').value));$('testSteerAxis').onchange=()=>{$('testSteerAxis').value=0;moveSettingsTest(0)};
const organizedSettingsMenu=showMenu;showMenu=function(tab='main'){const out=organizedSettingsMenu(...arguments);if(menuScreen==='options')syncSettingsPanel();return out};
const volumeBackupValidator=validateBackup;validateBackup=function(raw){const out=volumeBackupValidator(raw);for(const key of ['bgmVolume','sfxVolume']){const v=out.game.settings[key];if(v!==undefined&&(!Number.isFinite(v)||v<0||v>1))throw Error('Invalid audio volume');out.game.settings[key]=v??1}const sensitivity=out.game.settings.steeringSensitivity;if(sensitivity!==undefined&&(!Number.isFinite(sensitivity)||sensitivity<.5||sensitivity>1.5))throw Error('Invalid steering sensitivity');out.game.settings.steeringSensitivity=sensitivity??1;return out};
